results=function(){state.playing=false;modal(`<span class="eyebrow">THE CONVERSATION DOESN’T END HERE</span><h2 id="modal-title">You helped shape<br>what happened next.</h2><div class="stats"><div class="stat"><b>${state.actions.challenges}</b><span>Challenges introduced</span></div><div class="stat"><b>${state.actions.questions}</b><span>Your questions on stage</span></div><div class="stat"><b>${state.vote?'':'—'}</b><span>Audience vote</span></div></div><div class="recap-list"><div><b>01</b> The panel brought three different starting positions.</div><div><b>02</b> ${state.actions.challenges?'Your challenge opened an alternative exchange.':'Evidence and accountability complicated the original question.'}</div><div><b>03</b> ${state.onStage?esc(state.avatar.name)+' made a first demo appearance.':'Your own character could bring the next perspective.'}</div></div><div class="note">A recap of your local prototype session. No invented earnings or simulated scores are presented as real achievements.</div><div class="modal-actions"><button class="secondary" id="replay">Replay</button><button class="primary" id="join-next">${state.avatar?'Back to my studio':'Create my mind'} </button></div>`);$('#replay').onclick=()=>{close();state.turn=0;state.elapsed=0;state.branch=[];state.branchActive=null;state.playing=true;state.customLine='';updateTurn()};$('#join-next').onclick=()=>{close();if(state.avatar){state.view='studio';render()}else create()}};
